      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {a b : Polynomial R},\n  a.wronskian b ≠ 0 → (a.wronskian b).natDegree < a.natDegree + b.natDegree"
    },
    {
      "name": "IsCoprime.wronskian_eq_zero_iff",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [NoZeroDivisors R] {a b : Polynomial R},\n  IsCoprime a b → (a.wronskian b = 0 ↔ Polynomial.derivative a = 0 ∧ Polynomial.derivative b = 0)"
    },
    {
      "name": "Polynomial.wronskian_eq_of_sum_zero",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {a b c : Polynomial R}, a + b + c = 0 → a.wronskian b = b.wronskian c"
    }
  ]
}

